for(const row of researchedPrebuilts)sources['prebuilt_'+row.id]={publisher:row.merchant,title:row.name+' — listing '+row.sku,url:row.url,checked:'2026-10-11',access:'inspected',type:'retailer_configuration',scope:'Exact listing identity and CPU/GPU/RAM/storage configuration used as an illustrative research example. Original page title/body inspected; applicable seller details used where exposed.',limitations:'A research summary, not an eligible price or stock observation. Cached extraction dates vary. Marketplace, selected-variant and component-substitution questions remain visible. No retail photography, AI-generated FAQ performance claim or checkout guarantee used.',rights:'Citation and limited factual paraphrase only; no retailer media copied.'};
